import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.D6W-aSwD.js";const p=JSON.parse('{"title":"Standard Modes / External Flight Mode failures","description":"","frontmatter":{},"headers":[],"relativePath":"en/qgc-user-guide/troubleshooting/standard_modes.md","filePath":"en/qgc-user-guide/troubleshooting/standard_modes.md"}'),n={name:"en/qgc-user-guide/troubleshooting/standard_modes.md"};function s(d,e,i,l,c,g){return a(),o("div",null,e[0]||(e[0]=[r('<h1 id="standard-modes-external-flight-mode-failures" tabindex="-1">Standard Modes / External Flight Mode failures <a class="header-anchor" href="#standard-modes-external-flight-mode-failures" aria-label="Permalink to &quot;Standard Modes / External Flight Mode failures&quot;">​</a></h1><p>Standard Modes is a <a href="https://mavlink.io/en/services/standard_modes.html" target="_blank" rel="noreferrer">MAVLink microservice</a> through which supporting firmware (including PX4 and ArduPilot) advertises its flight modes to <em>QGroundControl</em> during the initial connection, using the <code>AVAILABLE_MODES</code>, <code>AVAILABLE_MODES_MONITOR</code> and <code>CURRENT_MODE</code> messages. This includes externally-registered flight modes.</p><p>If an expected flight mode does not appear in the flight-mode selector (or the wrong mode name is shown), the information needed to debug the problem is <em>QGroundControl&#39;s</em> internal processing of these messages. A MAVLink traffic capture alone is not sufficient, since it does not show how <em>QGroundControl</em> processed the messages.</p><h2 id="capturing-a-standard-modes-log" tabindex="-1">Capturing a Standard Modes log <a class="header-anchor" href="#capturing-a-standard-modes-log" aria-label="Permalink to &quot;Capturing a Standard Modes log&quot;">​</a></h2><ol><li>Open <strong>Application Settings &gt; App Log Viewer</strong> and click <strong>Categories</strong>.</li><li>Enable the <code>Vehicle.StandardModes</code> logging category.</li><li>Reproduce the problem: connect the vehicle (with any external modes already registered) and wait for the connection sequence to complete.</li><li>Back in the App Log Viewer, click <strong>Save</strong> to save the application log to a file.</li></ol><p>The log shows each <code>AVAILABLE_MODES</code> mode as it is received (name, index, standard mode, custom mode, and flags), when mode retrieval completes, and any request failures or re-requests triggered by <code>AVAILABLE_MODES_MONITOR</code> changes.</p><h2 id="reporting-an-issue" tabindex="-1">Reporting an issue <a class="header-anchor" href="#reporting-an-issue" aria-label="Permalink to &quot;Reporting an issue&quot;">​</a></h2><p>When <a href="./../support/support.html">reporting an issue</a>, attach the saved <em>QGroundControl</em> app log captured as described above. A MAVLink capture may be attached in addition, but is not a substitute for the app log.</p>',8)]))}const u=t(n,[["render",s]]);export{p as __pageData,u as default};
